package com.npcnicknametagger;

import net.runelite.client.config.*;

@ConfigGroup("NpcNicknameTagger")
public interface NpcNicknameTaggerConfig extends Config
{
    @ConfigItem(
        keyName = "replacements",
        name = "NPC replacements",
        description = "One per line: Npc Name,NewName",
        position = 0
    )
    default String replacements()
    {
        return "";
    }

    @Alpha
    @ConfigItem(
        keyName = "tileColor",
        name = "Tile color",
        description = "Color used for the NPC tile highlight",
        position = 1
    )
    default java.awt.Color tileColor()
    {
        return new java.awt.Color(0, 255, 255, 80);
    }

    @ConfigItem(
        keyName = "drawTileOutline",
        name = "Tile outline",
        description = "Draw an outline around the tile",
        position = 2
    )
    default boolean drawTileOutline()
    {
        return true;
    }

    @ConfigItem(
        keyName = "textShadow",
        name = "Text shadow",
        description = "Draw a subtle shadow behind overhead text",
        position = 3
    )
    default boolean textShadow()
    {
        return true;
    }
}

package com.npcnicknametagger;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;

import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.*;

public class NpcNicknameTaggerOverlay extends Overlay
{
    private final Client client;
    private final NpcNicknameTaggerPlugin plugin;
    private final NpcNicknameTaggerConfig config;

    @Inject
    private NpcNicknameTaggerOverlay(Client client, NpcNicknameTaggerPlugin plugin, NpcNicknameTaggerConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.MED);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        for (NPC npc : client.getNpcs())
        {
            if (npc == null || npc.getName() == null)
            {
                continue;
            }

            String key = npc.getName().toLowerCase();
            String replacement = plugin.getReplacements().get(key);
            if (replacement == null)
            {
                continue;
            }

            renderTile(g, npc);
            renderOverheadText(g, npc, replacement);
        }

        return null;
    }

    private void renderTile(Graphics2D g, NPC npc)
    {
        LocalPoint lp = npc.getLocalLocation();
        if (lp == null)
        {
            return;
        }

        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly == null)
        {
            return;
        }

        Color fill = config.tileColor();
        g.setColor(fill);
        g.fill(poly);

        if (config.drawTileOutline())
        {
            Color outline = new Color(fill.getRed(), fill.getGreen(), fill.getBlue(), Math.min(255, fill.getAlpha() + 80));
            g.setColor(outline);
            g.draw(poly);
        }
    }

    private void renderOverheadText(Graphics2D g, NPC npc, String text)
    {
        net.runelite.api.Point p = npc.getCanvasTextLocation(g, text, npc.getLogicalHeight() + 40);
        if (p == null)
        {
            return;
        }

        Font old = g.getFont();
        g.setFont(old.deriveFont(Font.BOLD, 14f));

        if (config.textShadow())
        {
            g.setColor(new Color(0, 0, 0, 180));
            g.drawString(text, p.getX() + 1, p.getY() + 1);
        }

        g.setColor(Color.WHITE);
        g.drawString(text, p.getX(), p.getY());

        g.setFont(old);
    }
}

package com.npcnicknametagger;

import com.google.inject.Provides;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "NPC Nickname Tagger",
    description = "Display a custom nickname above NPCs and optionally highlight their tiles"
)
public class NpcNicknameTaggerPlugin extends Plugin
{
    @Inject private OverlayManager overlayManager;
    @Inject private NpcNicknameTaggerOverlay overlay;
    @Inject private NpcNicknameTaggerConfig config;

    private final Map<String, String> replacements = new ConcurrentHashMap<>();

    Map<String, String> getReplacements()
    {
        return replacements;
    }

    @Override
    protected void startUp()
    {
        rebuildMap();
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        replacements.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged e)
    {
        if (!"NpcTagger".equals(e.getGroup()))
        {
            return;
        }
        rebuildMap();
    }

    private void rebuildMap()
    {
        replacements.clear();

        String raw = config.replacements();
        if (raw == null || raw.trim().isEmpty())
        {
            return;
        }

        for (String line : raw.split("\\r?\\n"))
        {
            line = line.trim();
            if (line.isEmpty() || line.startsWith("#"))
            {
                continue;
            }

            int comma = line.indexOf(',');
            if (comma <= 0 || comma >= line.length() - 1)
            {
                continue;
            }

            String npcName = line.substring(0, comma).trim().toLowerCase();
            String newName = line.substring(comma + 1).trim();

            if (!npcName.isEmpty() && !newName.isEmpty())
            {
                replacements.put(npcName, newName);
            }
        }
    }

    @Provides
    NpcNicknameTaggerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(NpcNicknameTaggerConfig.class);
    }
}
